WITH pd AS MATERIALIZED (SELECT match_id,player_slot,arg_max(struct_pack(team:=team,w:=winning_team,b:=average_badge,lane:=assigned_lane,ts:="stats.time_stamp_s",nw:="stats.net_worth"),created_at) AS v FROM match_player WHERE match_id>=106000000 AND match_id<107000000 AND game_mode='Normal' AND match_mode='Ranked' AND match_outcome='TeamWin' AND average_badge BETWEEN 10 AND 119 GROUP BY match_id,player_slot), a AS (SELECT match_id,CASE WHEN grouping(v.lane)=1 THEN 'team' ELSE v.lane::VARCHAR END AS lane,any_value(v.w) AS w,any_value(v.b) AS b,count(*) AS n,count(v.nw[list_position(v.ts,540)]) AS valid,count(*) FILTER(v.team='Team0') AS n0,count(*) FILTER(v.team='Team1') AS n1,sum(v.nw[list_position(v.ts,540)]) FILTER(v.team='Team0') AS s0,sum(v.nw[list_position(v.ts,540)]) FILTER(v.team='Team1') AS s1 FROM pd WHERE v.lane IN (1,4,6) AND len(v.ts)=len(v.nw) GROUP BY GROUPING SETS ((match_id),(match_id,v.lane))), c AS (SELECT *,CASE WHEN b<50 THEN 'low' WHEN b<80 THEN 'mid' ELSE 'high' END AS elo,CASE WHEN s0>s1 THEN 'Team0' ELSE 'Team1' END AS leader FROM a WHERE valid=n AND ((lane='team' AND n0=6 AND n1=6) OR (lane<>'team' AND n0=2 AND n1=2)) AND greatest(s0,s1)>1.05*least(s0,s1)) SELECT lane,elo,count(*) AS n,count(*) FILTER(w=leader) AS wins FROM c GROUP BY GROUPING SETS ((lane),(lane,elo)) ORDER BY lane,elo;
